\label{lem:avg}
For all $t \geq 1$ and consider Algorithm~\ref{algo:main}, it holds that\vspace{-.1cm}
\begin{equation} \label{eq:track} \textstyle
{\bm g}_{\bm{\theta}}(t)  = \frac{1}{NM} \sum_{i=1}^N
\sum_{p=1}^M {\nabla}_{\bm{\theta}} J_{i,p} ( \bm{\theta}_i^{\tau_p^t}, {\bm w}_i^{\tau_p^t} ) \;.\vspace{-.2cm}
\end{equation}

We first define a set of notations pertaining to the proof. 
For any $\beta > 0$, observe that the primal-dual optimal solution,
$(  \bm{\theta}^\star, \{ {\bm w}_i ^{\star}\}_{i=1}^N )$,  
to the optimization problem  \eqref{eq:opt_pd} can be written as 
\begin{equation} \label{eq:opt_cond}
\underbrace{\left( 
\begin{array}{cccc}
\rho {\bm I} & \sqrt{\frac{\beta}{N}} \hat{\bm A}^\top & \cdots & \sqrt{\frac{\beta}{N}} \hat{\bm A}^\top \\
-\sqrt{\frac{\beta}{N}} \hat{\bm A} & \beta \hat{\bm C} & \cdots & \cdots \\
\vdots & {\bm 0} & \ddots & {\bm 0} \\
-\sqrt{\frac{\beta}{N}} \hat{\bm A} & \cdots & \cdots & \beta \hat{\bm C} 
\end{array}
\right)}_{\mathrel{\mathop:}= {\bm G}}
\left( \begin{array}{c}
\bm{\theta}^\star \\
\frac{1}{\sqrt{\beta N}}{\bm w}_1^\star \\
\vdots \\
\frac{1}{\sqrt{\beta N}}{\bm w}_N^\star 
\end{array}
\right) 
= 
\left( \begin{array}{c}
{\bm 0} \\
-\sqrt{\frac{\beta}{N}}{\bm b}_1 \\
\vdots \\
-\sqrt{\frac{\beta}{N}}{\bm b}_N 
\end{array}
\right) \;, 
\end{equation}
where we  denote the matrix on the left hand side as ${\bm G}$.  This equation can be obtained by checking the first-order optimality condition. In addition, for any $p \in \{ 1, \ldots, M \}$, we  define the  ${\bm G}_p$ as 
\begin{equation}\label{eq:matrix_Gp}
{\bm G}_p \mathrel{\mathop:}= \left( 
\begin{array}{cccc}
\rho {\bm I} & \sqrt{\frac{\beta}{N}} {\bm A}_p^\top & \cdots & \sqrt{\frac{\beta}{N}} {\bm A}^\top \\
-\sqrt{\frac{\beta}{N}}{\bm A}_p & \beta {\bm C}_p & \cdots & \cdots \\
\vdots & {\bm 0} & \ddots & {\bm 0} \\
-\sqrt{\frac{\beta}{N}}{\bm A}_p & \cdots & \cdots & \beta {\bm C}_p
\end{array}
\right) \;.
\end{equation} 
By definition, ${\bm G}$ is the sample average of $ \{ {\bm G}_p \}_{p=1}^M$.
Define $\bar{\bm{\theta}}(t) \mathrel{\mathop:}= (1/N) \sum_{i=1}^N \bm{\theta}_i^t$ as the average of the local parameters at iteration $t$. Furthermore, we define
\begin{align}
	{\bm h}_{\bm{\theta}}(t)  \mathrel{\mathop:}= \rho \bar{\bm{\theta}}(t) + \frac{1}{N} \sum_{i=1}^N \hat{\bm A}^\top {\bm w}_i^t, & \qquad {\bm g}_{\bm{\theta}}(t) \mathrel{\mathop:}= \frac{1}{NM} \sum_{i=1}^N \sum_{p=1}^M \big( \rho \bm{\theta}_i^{\tau_p^t} + {\bm A}_p^\top {\bm w}_i^{\tau_p^t} \big)  \;, \label{eq:4terms_1}  \\
	{\bm h}_{ {\bm w}_i } (t) \mathrel{\mathop:}= \hat{\bm A} \bar{\bm{\theta}}(t) - \hat{\bm C} {\bm w}_i^t - \hat{\bm b}_i, & \qquad 
	{\bm g}_{ {\bm w}_i } (t) \mathrel{\mathop:}= \frac{1}{M} \sum_{p=1}^M \big( {\bm A}_p \bm{\theta}_i^{\tau_p^t} - {\bm C}_p {\bm w}_i^{\tau_p^t} - {\bm b}_{p,i} \big) \;, \label{eq:4terms_2}
\end{align}
where ${\bm h}_{\bm{\theta}}(t)$ and $ {\bm h}_{\bm w}(t) : = [{\bm h}_{ {\bm w}_1} (t), \cdots, 	{\bm h}_{ {\bm w}_N } (t)]$ represent the gradients evaluated by a \emph{centralized} and 
\emph{batch} algorithm. 
Note that ${\bm g}_{\bm{\theta}}(t)$ defined in \eqref{eq:4terms_1} coincides with that in \eqref{eq:track}.
Using Lemma~\ref{lem:avg}, 
it can be checked that $\bar{\bm{\theta}}(t+1) = \bar{\bm{\theta}}(t) - \gamma_1 {\bm g}_{\bm{\theta}}(t)$
and ${\bm w}_i^{t+1} = {\bm w}_i^t - \gamma_2 {\bm g}_{ {\bm w}_i } (t)$
for all $t \geq 1$.
That is, $\bar{\bm{\theta}}(t+1)$ and ${\bm w}_i^{t+1} $ can be viewed as primal-dual updates using  ${\bm g}_{\bm{\theta}}(t)$ and ${\bm g}_{ {\bm w}_i } (t)$, which are decentralized counterparts of gradients ${\bm h}_{\bm{\theta}}(t)$ and ${\bm h}_{ {\bm w}_i} (t)$ defined in \eqref{eq:4terms_1} \eqref{eq:4terms_2}.
